fullFile.code:
import { Component, ViewEncapsulation } from '@angular/core';

// ❌ OLD: Emulated scoping rewrites `p` to `p[_ngcontent-abc]`, so the
// rule only matches the component's own <p> tags. But it is NOT a real
// boundary: a global `p { color: blue }` rule with higher/later
// specificity still wins, and inherited properties (color, font) leak
// in from outside.
@Component({
  selector: 'app-card',
  encapsulation: ViewEncapsulation.Emulated, // ❌ OLD: attribute-based scoping
  styles: [`
    p { color: red; }
  `],
  template: `<p>Card text</p>`,
})
export class CardComponent {
  // ❌ OLD: if the page sets `p { color: blue !important }`, this red
  // rule loses — no real isolation against global styles.
}

