  styles: ['p { color: red; }'],
})

fullFile.code:
import { Component, ViewEncapsulation } from '@angular/core';

// ✅ NEW: ShadowDom puts the template and styles inside a real shadow
// root. Outer styles cannot match inner elements at all, and inner
// styles cannot leak out — true isolation.
@Component({
  selector: 'app-card',
  encapsulation: ViewEncapsulation.ShadowDom, // ✅ NEW: real boundary
  styles: [`
    p { color: red; } // ✅ NEW: fully isolated from page styles
  `],
  template: `<p>Card text</p>`,
})
export class CardComponent {
  // Global `p { color: blue }` rules now bounce off the shadow root.
  // To style internals from outside, expose parts:
  //   host: { 'part': 'card-body' }  ->  ::part(card-body) { ... }
}
